package com.pcguard.agent.detector;
import com.pcguard.agent.config.AgentConfig; import com.pcguard.agent.model.*; import com.pcguard.agent.model.Enums.*; import java.time.Instant; import java.util.*;

/** Converts stable threshold violations into faults; null sensor values deliberately produce no false alarm. */
public final class ThresholdDetector implements FaultDetector {
 private final AgentConfig c;
 public ThresholdDetector(AgentConfig c){this.c=c;}
 public List<Fault> detect(Snapshot s){ List<Fault> out=new ArrayList<>(); check(out,s,"HIGH_CPU_USAGE",FaultCategory.CPU,"CPU","usagePercent",num(s.cpu(),"usagePercent"),c.number("threshold.cpu.warning"),c.number("threshold.cpu.critical"),"CPU usage has remained elevated.","Review running processes and workload."); check(out,s,"HIGH_MEMORY_USAGE",FaultCategory.MEMORY,"RAM","usagePercent",num(s.memory(),"usagePercent"),c.number("threshold.memory.warning"),c.number("threshold.memory.critical"),"Memory usage is elevated.","Close unnecessary applications or add memory."); check(out,s,"HIGH_CPU_TEMPERATURE",FaultCategory.TEMPERATURE,"CPU","temperatureCelsius",num(s.sensors(),"cpuTemperatureCelsius"),c.number("threshold.temperature.warning"),c.number("threshold.temperature.critical"),"CPU temperature is elevated.","Check airflow and cooling; do not ignore persistent heat.");
  Double available=num(s.memory(),"availableBytes"); if(available!=null && available < c.number("threshold.memory.available-mb")*1024*1024) out.add(fault(s,"LOW_AVAILABLE_MEMORY",FaultCategory.MEMORY,"RAM","availableBytes",available,c.number("threshold.memory.available-mb")*1024*1024,FaultSeverity.WARNING,"Available memory is low.","Close unnecessary applications."));
  for(Map<String,Object>d:s.storage()){ Double usage=num(d,"usagePercent"),free=num(d,"freeBytes"); check(out,s,"LOW_DISK_SPACE",FaultCategory.STORAGE,String.valueOf(d.get("mount")),"usagePercent",usage,c.number("threshold.disk.warning"),c.number("threshold.disk.critical"),"Disk usage is high.","Free space or expand storage."); if(free!=null && free<c.number("threshold.disk.critical-free-mb")*1024*1024) out.add(fault(s,"CRITICAL_DISK_SPACE",FaultCategory.STORAGE,String.valueOf(d.get("mount")),"freeBytes",free,c.number("threshold.disk.critical-free-mb")*1024*1024,FaultSeverity.CRITICAL,"Disk free space is critically low.","Free disk space immediately.")); }
  Double battery=num(s.battery(),"remainingPercent"); if(battery!=null) lowCheck(out,s,"LOW_BATTERY",FaultCategory.BATTERY,"Battery","remainingPercent",battery,c.number("threshold.battery.warning"),c.number("threshold.battery.critical"),"Battery charge is low.","Connect power or shut down safely.");
  if(!s.network().isEmpty() && s.network().stream().noneMatch(n->Boolean.TRUE.equals(n.get("up")))) out.add(fault(s,"NETWORK_DISCONNECTED",FaultCategory.NETWORK,"Network","interfaceUp",0d,1d,FaultSeverity.WARNING,"No active network interface was found.","Check the network adapter and cable/Wi-Fi connection."));
  if(s.uptimeSeconds()>c.number("threshold.uptime.days")*86400) out.add(fault(s,"LONG_UPTIME",FaultCategory.OS,"Operating System","uptimeDays",s.uptimeSeconds()/86400d,c.number("threshold.uptime.days"),FaultSeverity.WARNING,"System uptime is unusually long.","Schedule a restart when appropriate.")); return out; }
 private void check(List<Fault>out,Snapshot s,String code,FaultCategory cat,String component,String metric,Double value,double warning,double critical,String msg,String action){if(value!=null&&value>=warning)out.add(fault(s,code,cat,component,metric,value,value>=critical?critical:warning,value>=critical?FaultSeverity.CRITICAL:FaultSeverity.WARNING,msg,action));}
 private void lowCheck(List<Fault>out,Snapshot s,String code,FaultCategory cat,String component,String metric,Double value,double warning,double critical,String msg,String action){if(value!=null&&value<=warning)out.add(fault(s,code,cat,component,metric,value,value<=critical?critical:warning,value<=critical?FaultSeverity.CRITICAL:FaultSeverity.WARNING,msg,action));}
 private Fault fault(Snapshot s,String code,FaultCategory cat,String component,String metric,Double current,Double threshold,FaultSeverity severity,String message,String action){return new Fault(String.valueOf(s.identity().get("computerId")),String.valueOf(s.identity().get("hostname")),Instant.now(),code,cat,component,metric,current,threshold,severity,FaultState.ACTIVE,message,action);}
 private static Double num(Map<String,Object> values,String k){Object v=values.get(k); return v instanceof Number n?n.doubleValue():null;}
}
